# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ATMOSFER BASINCI VE BASINCI ETKİLEYEN TEMEL FAKTÖRLER</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">TERS ORANTILI FAKTÖRLER (Artınca Basınç Azalır)</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">1. Sıcaklık (Termik Etki):</text>\n  <text x="43" y="114" font-size="10.5" fill="#1d4ed8">Isınan hava genleşir, hafifler ve yükselir → Alçak Basınç (AB).</text>\n  <text x="43" y="130" font-size="10.5" fill="#1d4ed8">Soğuyan hava ağırlaşır ve alçalır → Yüksek Basınç (YB).</text>\n  <text x="35" y="158" font-size="11" font-weight="bold" fill="#1e3a8a">2. Yükselti:</text>\n  <text x="43" y="176" font-size="10.5" fill="#1d4ed8">Yerden yükseldikçe atmosfer kalınlığı ve gaz yoğunluğu</text>\n  <text x="43" y="192" font-size="10.5" fill="#1d4ed8">azaldığı için basınç her yerde düzenli olarak AZALIR.</text>\n  <text x="35" y="220" font-size="10.5" font-weight="bold" fill="#b91c1c">Normal Basınç: 1013 mb (hPa) = 760 mmHg (45° enlemi, 0 m, 15 °C)</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">DOĞRU ORANTILI VE DİNAMİK FAKTÖRLER</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#14532d">3. Yer Çekimi (Enlem Etkisi):</text>\n  <text x="383" y="114" font-size="10.5" fill="#166534">Ekvator\'dan kutuplara doğru yer çekimi arttığı için</text>\n  <text x="383" y="130" font-size="10.5" fill="#166534">gazların yoğunluğu ve atmosfer basıncı ARTAR.</text>\n  <text x="375" y="158" font-size="11" font-weight="bold" fill="#14532d">4. Yoğunluk: Gaz yoğunluğu arttıkça basınç ARTAR.</text>\n  <text x="375" y="184" font-size="11" font-weight="bold" fill="#14532d">5. Dinamik Etkenler (Günlük Hareket):</text>\n  <text x="383" y="202" font-size="10.5" fill="#166534">Dünya\'nın ekseni etrafında dönmesiyle 30° enlemlerinde</text>\n  <text x="383" y="218" font-size="10.5" fill="#166534">Dinamik YB, 60° enlemlerinde Dinamik AB kuşakları oluşur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ALÇAK BASINÇ (SİKLON) VE YÜKSEK BASINÇ (ANTİSİKLON) KARŞILAŞTIRMASI</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9f1239">ALÇAK BASINÇ — AB (&lt; 1013 mb / Siklon)</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#881337">• Dikey Hava Hareketi: YÜKSELİCİDİR (↑)</text>\n  <text x="35" y="120" font-size="11" font-weight="bold" fill="#881337">• Yatay Hava Hareketi: Çevreden merkeze doğrudur.</text>\n  <text x="35" y="144" font-size="10.5" fill="#9f1239">• Yükselen hava soğur, bağıl nem artar, bulutluluk ve</text>\n  <text x="43" y="160" font-size="10.5" font-weight="bold" fill="#b91c1c">YAĞIŞ OLASILIĞI YÜKSEKTİR (Hava kapalıdır).</text>\n  <text x="35" y="186" font-size="10.5" fill="#9f1239">• Nem fazla olduğu için günlük sıcaklık farkı AZDIR.</text>\n  <text x="35" y="212" font-size="10.5" font-weight="bold" fill="#881337">• Sürekli Merkezler: 0° Termik AB ve 60° Dinamik AB</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">YÜKSEK BASINÇ — YB (&gt; 1013 mb / Antisiklon)</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">• Dikey Hava Hareketi: ALÇALICIDIR (↓)</text>\n  <text x="375" y="120" font-size="11" font-weight="bold" fill="#1e3a8a">• Yatay Hava Hareketi: Merkezden çevreye doğrudur.</text>\n  <text x="375" y="144" font-size="10.5" fill="#1d4ed8">• Alçalan hava ısınır, nem açığı büyür; hava açık ve</text>\n  <text x="383" y="160" font-size="10.5" font-weight="bold" fill="#15803d">GÜNEŞLİDİR, YAĞIŞ OLASILIĞI DÜŞÜKTÜR (Ayaz/Kurak).</text>\n  <text x="375" y="186" font-size="10.5" fill="#1d4ed8">• Bulutsuz olduğu için günlük sıcaklık farkı FAZLADIR.</text>\n  <text x="375" y="212" font-size="10.5" font-weight="bold" fill="#1e3a8a">• Sürekli Merkezler: 30° Dinamik YB ve 90° Termik YB</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">RÜZGÂRLARIN OLUŞUMU VE RÜZGÂR TÜRLERİ (SÜREKLİ, MEVSİMLİK, YEREL)</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">1. SÜREKLİ RÜZGÂRLAR</text>\n  <text x="32" y="94" font-size="10.5" font-weight="bold" fill="#78350f">• Alize Rüzgârları:</text>\n  <text x="38" y="110" font-size="10" fill="#92400e">30° DYB → 0° TAB (Tropikal kuşak)</text>\n  <text x="32" y="136" font-size="10.5" font-weight="bold" fill="#78350f">• Batı Rüzgârları:</text>\n  <text x="38" y="152" font-size="10" fill="#92400e">30° DYB → 60° DAB (Orta kuşak, Türkiye)</text>\n  <text x="32" y="178" font-size="10.5" font-weight="bold" fill="#78350f">• Kutup Rüzgârları:</text>\n  <text x="38" y="194" font-size="10" fill="#92400e">90° TYB → 60° DAB (Soğuk kuşak)</text>\n  <text x="32" y="220" font-size="9.5" font-weight="bold" fill="#b91c1c">KYK\'de sağa, GYK\'de sola sapar.</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. MEVSİMLİK (MUSON)</text>\n  <text x="257" y="94" font-size="10.5" font-weight="bold" fill="#14532d">• Yaz Musonu (Okyanus → Kara):</text>\n  <text x="263" y="110" font-size="10" fill="#166534">Hint Okyanusu\'ndan (YB) Güney Asya</text>\n  <text x="263" y="124" font-size="10" fill="#166534">karasına (AB) eser; bol yağış bırakır.</text>\n  <text x="257" y="152" font-size="10.5" font-weight="bold" fill="#14532d">• Kış Musonu (Kara → Okyanus):</text>\n  <text x="263" y="168" font-size="10" fill="#166534">Asya karasından (YB) okyanusa (AB)</text>\n  <text x="263" y="182" font-size="10" fill="#166534">doğru eser; kuru ve yağışsızdır.</text>\n  <text x="257" y="214" font-size="9.5" font-weight="bold" fill="#15803d">Neden: Yıllık hareket ve kara-deniz farkı</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">3. YEREL RÜZGÂRLAR</text>\n  <text x="482" y="94" font-size="10.5" font-weight="bold" fill="#581c87">• Meltemler (Günlük):</text>\n  <text x="488" y="110" font-size="10" fill="#6b21a8">Deniz-Kara ve Vadi-Dağ meltemi.</text>\n  <text x="482" y="136" font-size="10.5" font-weight="bold" fill="#581c87">• Föhn (Fön) Rüzgârı:</text>\n  <text x="488" y="152" font-size="10" fill="#6b21a8">Dağdan alçalan, her 100 m\'de 1 °C</text>\n  <text x="488" y="166" font-size="10" fill="#6b21a8">ısınan sıcak ve kurutucu rüzgâr.</text>\n  <text x="482" y="192" font-size="10.5" font-weight="bold" fill="#581c87">• Türkiye (Kayıp Sakal):</text>\n  <text x="488" y="208" font-size="10" fill="#b91c1c">Soğuk: Karayel, Yıldız, Poyraz</text>\n  <text x="488" y="222" font-size="10" fill="#dc2626">Sıcak: Samyeli, Kıble, Lodos</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
